package com.byawasaya.platform.plans;
import java.time.Instant; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus;
@RestController @RequestMapping("/api/promotions") public class PublicPromotionController {
 private final JdbcTemplate jdbc; public PublicPromotionController(JdbcTemplate jdbc){this.jdbc=jdbc;}
 @GetMapping("/validate") public Map<String,Object> validate(@RequestParam String code,@RequestParam String planCode){List<Map<String,Object>> rows=jdbc.queryForList("SELECT code,discount_type,discount_value,starts_at,ends_at,max_redemptions,redeemed_count,eligible_plan_codes,active FROM promo_codes WHERE code=?",code.trim().toUpperCase(Locale.ROOT));if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Promo code is not valid.");Map<String,Object> p=rows.get(0);Instant now=Instant.now();if(!Boolean.TRUE.equals(p.get("active"))||instant(p.get("starts_at")).isAfter(now)||(p.get("ends_at")!=null&&!instant(p.get("ends_at")).isAfter(now)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Promo code is not currently active.");Object max=p.get("max_redemptions");if(max!=null&&((Number)p.get("redeemed_count")).longValue()>=((Number)max).longValue())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Promo code has reached its redemption limit.");String eligible=String.valueOf(p.get("eligible_plan_codes"));if(!eligible.contains("\""+planCode+"\"")&&!"[]".equals(eligible))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Promo code does not apply to the selected plan.");return Map.of("valid",true,"code",p.get("code"),"discountType",p.get("discount_type"),"discountValue",p.get("discount_value"));}
 private Instant instant(Object v){if(v instanceof Instant i)return i;if(v instanceof java.time.OffsetDateTime o)return o.toInstant();if(v instanceof java.sql.Timestamp t)return t.toInstant();return Instant.now();}
}
